<?= $this->section('styles') ?><style>.patient-video-card{max-width:1050px;border:0;border-radius:1rem;box-shadow:0 1rem 2.5rem rgba(15,23,42,.12)}.patient-video-stage{position:relative;display:grid;min-height:30rem;grid-template-columns:1fr 1fr;gap:1rem;padding:1rem;border-radius:.9rem;background:linear-gradient(135deg,#101827,#1d2b42);overflow:hidden}.patient-video-placeholder{position:absolute;inset:0;z-index:2;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:.6rem;color:#c9d2df;text-align:center;background:radial-gradient(circle at center,rgba(42,67,101,.65),rgba(16,24,39,.96));transition:opacity .2s ease}.patient-video-placeholder.is-hidden{opacity:0;pointer-events:none}.patient-video-placeholder i{font-size:2.8rem;color:#8ab8ff}.patient-video-placeholder strong{color:#fff;font-size:1.1rem}.patient-video-local,.patient-video-remote{position:relative;min-height:26rem;border-radius:.7rem;overflow:hidden;background:#26364e;border:1px solid rgba(255,255,255,.12)}.patient-video-local:before,.patient-video-remote:before{position:absolute;z-index:1;left:.75rem;bottom:.65rem;padding:.25rem .55rem;border-radius:.35rem;background:rgba(0,0,0,.6);color:#fff;font-size:.72rem;content:'You'}.patient-video-remote:before{content:'Doctor'}.patient-video-stage video,.twilio-video-track{display:block;width:100%;height:100%;min-height:26rem;object-fit:cover;background:#111827}.patient-video-remote:empty,.patient-video-local:empty{display:block}.patient-video-stage.is-video-connected .patient-video-local:empty:after,.patient-video-stage.is-video-connected .patient-video-remote:empty:after{display:flex;align-items:center;justify-content:center;height:100%;min-height:26rem;color:#b9c7da;font-size:.9rem;content:'Waiting for video…'}@media(max-width:767px){.patient-video-stage{grid-template-columns:1fr;min-height:25rem}.patient-video-local,.patient-video-remote,.patient-video-stage video,.twilio-video-track{min-height:12rem}.patient-video-stage.is-video-connected .patient-video-local:empty:after,.patient-video-stage.is-video-connected .patient-video-remote:empty:after{min-height:12rem}}</style><?= $this->endSection() ?>
<?= $this->section('scripts') ?><script src="https://sdk.twilio.com/js/video/releases/2.29.0/twilio-video.min.js"></script><script src="<?= base_url('assets/js/video/twilio-room.js?v=20261030.5') ?>"></script><script src="<?= base_url('assets/js/video/video-ui.js?v=20261030.1') ?>"></script><script>
$(function(){var button=$('#patient-video-join'),message=$('#patient-video-message'),page=$('#patient-video-page'),poller=null,connected=false,connecting=false;function setStatus(value){$('#patient-video-status').text('Status: '+value.replace(/_/g,' ').replace(/\b\w/g,function(c){return c.toUpperCase();}));}function explain(error){var name=error&&error.name||'',text=error&&error.message||'';if(name==='NotAllowedError'||name==='PermissionDeniedError')return'Camera or microphone permission was denied. Allow access in the browser address-bar settings, then try again.';if(name==='NotFoundError')return'No camera or microphone was found on this device.';if(name==='NotReadableError')return'The camera or microphone is already being used by another application.';return text?('Video connection failed: '+text):'Camera or microphone permission or connection failed.';}function join(){if(connected||connecting)return;var b=button,csrf=$('input[name="csrf_rtn"]').val()||'';connecting=true;b.prop('disabled',true);message.text('Connecting to the secure consultation room…');$.ajax({url:b.data('token-url'),method:'POST',dataType:'json',headers:{'X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':csrf},data:{csrf_rtn:csrf},success:function(r){if(!r.status||!r.data||!r.data.token){message.text((r&&r.msg)||'Video consultation is not available yet.');connecting=false;b.prop('disabled',false);return;}window.RootinsTwilioRoom.connect(r.data.token,document.getElementById('patient-video-stage')).then(function(){connected=true;connecting=false;page.addClass('is-video-connected');b.html('<i class="bi bi-check-circle mr-1"></i>Connected');setStatus('connected');message.text('You are connected to your doctor.');$('#patient-video-mute,#patient-video-camera').prop('disabled',false);}).catch(function(error){console.error(error);connecting=false;message.text(explain(error));b.prop('disabled',false);});},error:function(xhr){var response=xhr.responseJSON||{};connecting=false;message.text((response.msg||response.message)||'Video service is not available yet. Please try again.');b.prop('disabled',false);}});}function pollStatus(){if(connected)return;$.getJSON('<?= base_url('patient/video/' . $appointmentId . '/status') ?>',function(r){var session=r&&r.data?r.data.session:null;if(session&&['waiting','active'].indexOf(session.status)!==-1){setStatus(session.status);button.prop('disabled',false);message.text('Your doctor has started the consultation. You can join now.');if(!connecting)join();}});}button.on('click',join);$('#patient-video-mute').on('click',function(){var active=$(this).data('active')===true;$(this).data('active',!active).toggleClass('active',!active).html(!active?'<i class="bi bi-mic-mute mr-1"></i>Unmute':'<i class="bi bi-mic mr-1"></i>Mute');if(window.RootinsTwilioRoom){if(!active)window.RootinsTwilioRoom.mute();else window.RootinsTwilioRoom.unmute();}});$('#patient-video-camera').on('click',function(){var active=$(this).data('active')===true;$(this).data('active',!active).toggleClass('active',!active).html(!active?'<i class="bi bi-camera-video-off mr-1"></i>Camera on':'<i class="bi bi-camera-video mr-1"></i>Camera off');if(window.RootinsTwilioRoom){if(!active)window.RootinsTwilioRoom.cameraOff();else window.RootinsTwilioRoom.cameraOn();}});if(['waiting','active'].indexOf('<?= esc($status) ?>')===-1){poller=window.setInterval(pollStatus,5000);}else{window.setTimeout(join,250);}$(window).on('beforeunload.patientVideo',function(){if(poller)window.clearInterval(poller);if(window.RootinsTwilioRoom)window.RootinsTwilioRoom.disconnect();});});
</script><?= $this->endSection() ?>
